import type { SeedCharacter } from "./seedCharacters";

function iid(slug: string, n: number) {
  return `seed_${slug}_item_${String(n).padStart(3, "0")}`;
}
function gid(slug: string, n: number) {
  return `seed_${slug}_gallery_${n}`;
}

